import { Component, Input } from '@angular/core';
import { HealthData } from '../../models/health-data.model';

@Component({
  selector: 'app-daily-stats',
  templateUrl: './daily-stats.component.html',
  styleUrls: ['./daily-stats.component.scss']
})
export class DailyStatsComponent {
  @Input() healthData: HealthData | null = null;

  formatValue(value: number | null | undefined): string {
    if (value === null || value === undefined) return 'N/A';
    return value.toLocaleString();
  }
}
<div class="grid grid-cols-2 gap-4">
  <div class="stat-card">
    <div class="text-3xl font-bold text-cyan mb-1">{{ formatValue(healthData?.steps) }}</div>
    <div class="text-sm text-grey">Steps</div>
  </div>
  <div class="stat-card">
    <div class="text-3xl font-bold text-cyan mb-1">{{ formatValue(healthData?.calories) }}</div>
    <div class="text-sm text-grey">Calories</div>
  </div>
  <div class="stat-card">
    <div class="text-3xl font-bold text-cyan mb-1">{{ formatValue(healthData?.heartRate) }}</div>
    <div class="text-sm text-grey">Heart Rate</div>
  </div>
  <div class="stat-card">
    <div class="text-3xl font-bold text-cyan mb-1">{{ formatValue(healthData?.distanceKm) }}</div>
    <div class="text-sm text-grey">Distance (km)</div>
  </div>
</div>
